/*
 * core/dict/safir_deinflect.c
 *
 * Japanese deinflection by chained suffix rules, the way Yomitan does it. The table
 * (safir_deinflect_rules.h, generated by tools/gen_deinflect_rules.py) says, for each
 * rule, what kind of word the input must be and what kind the result is. Starting from
 * the surface text, rules are applied breadth-first until no rule fits:
 *
 *   見ていた  -past->  見ている (v1)  -te iru->  見て (-te)  -te->  見る (v1)
 *   行かなきゃ -ya-> 行かなければ (-ba) -ba-> 行かない (adj-i) -negative-> 行く (v5)
 *
 * The old table matched whole suffixes in one step, so any combination it did not list
 * (見ていた, 読んでしまった, 言われてる...) fell back to a shorter, wrong word.
 */
#include "safir_deinflect.h"
#include <string.h>

#include "safir_deinflect_rules.h"

#define RULE_COUNT (sizeof(s_rules) / sizeof(s_rules[0]))

static uint16_t conds_to_pos(uint16_t conds) {
    uint16_t pos = 0;
    if (conds & C_V1) pos |= SAFIR_POS_VERB_ICHIDAN;
    if (conds & C_V5) pos |= SAFIR_POS_VERB_GODAN;
    if (conds & (C_VS | C_VZ)) pos |= SAFIR_POS_VERB_SURU;
    if (conds & C_VK) pos |= SAFIR_POS_VERB_KURU;
    if (conds & C_ADJI) pos |= SAFIR_POS_ADJ_I;
    return pos;
}

static bool already_have(const SafirDeinflectCandidate *c, size_t n, const char *term, uint16_t conds) {
    for (size_t i = 0; i < n; ++i) {
        if (c[i].conds == conds && strcmp(c[i].term, term) == 0) return true;
    }
    return false;
}

/* dst = name, or name+rest; cut at a '+' boundary if it does not fit. */
static void trace_prepend(char *dst, size_t cap, const char *name, const char *rest) {
    size_t n = strlen(name);
    if (n >= cap) n = cap - 1;
    memcpy(dst, name, n);
    size_t r = strlen(rest);
    if (r > 0 && n + 1 + r < cap) {
        dst[n++] = '+';
        memcpy(dst + n, rest, r);
        n += r;
    } else if (r > 0 && n + 4 < cap) {
        memcpy(dst + n, "+..", 3);
        n += 3;
    }
    dst[n] = '\0';
}

size_t safir_deinflect(const char *surface, SafirDeinflectCandidate *out, size_t max_candidates) {
    if (!surface || !out || max_candidates == 0) return 0;
    size_t surf_len = strlen(surface);
    if (surf_len >= sizeof(out[0].term)) surf_len = sizeof(out[0].term) - 1;

    memcpy(out[0].term, surface, surf_len);
    out[0].term[surf_len] = '\0';
    out[0].pos_mask = SAFIR_POS_ALL;
    out[0].conds = 0xFFFF; /* anything: every rule may start here */
    out[0].steps = 0;
    out[0].rule_trace[0] = '\0';
    size_t count = 1;

    for (size_t q = 0; q < count && count < max_candidates; ++q) {
        /* Copy: out[] may not move, but keep the source stable while appending. */
        const SafirDeinflectCandidate src = out[q];
        if (src.steps >= SAFIR_DEINFLECT_MAX_STEPS) continue;
        size_t len = strlen(src.term);

        for (size_t r = 0; r < RULE_COUNT && count < max_candidates; ++r) {
            const DeinflectRule *rule = &s_rules[r];
            if (!(src.conds & rule->cond_in)) continue;
            if (rule->in_len > len) continue;
            /* The rule must leave a stem: "た" alone is not a verb, "ない" is not "る".
             * Whole-word rules (した -> する, 来た -> 来る) are fine. */
            if (rule->in_len == len && rule->out_len <= 3) continue;
            if (memcmp(src.term + len - rule->in_len, rule->in, rule->in_len) != 0) continue;

            size_t stem = len - rule->in_len;
            if (stem + rule->out_len >= sizeof(src.term)) continue;

            char term[sizeof(src.term)];
            memcpy(term, src.term, stem);
            memcpy(term + stem, rule->out, rule->out_len);
            term[stem + rule->out_len] = '\0';
            if (term[0] == '\0') continue;
            if (already_have(out, count, term, rule->cond_out)) continue;

            SafirDeinflectCandidate *c = &out[count++];
            memcpy(c->term, term, stem + rule->out_len + 1);
            c->conds = rule->cond_out;
            c->pos_mask = (rule->cond_out & C_DICT_FORMS) ? conds_to_pos(rule->cond_out) : 0;
            c->steps = (uint8_t)(src.steps + 1);
            /* The rule just undone sits closer to the base than everything before it. */
            trace_prepend(c->rule_trace, sizeof(c->rule_trace), s_rule_names[rule->name], src.rule_trace);
        }
    }
    return count;
}
